def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def get_first_pos(obj, keys):
        if isinstance(obj, dict):
            for k in keys:
                if k in obj:
                    p = as_pos(obj.get(k))
                    if p is not None:
                        return p
            for k, v in obj.items():
                if isinstance(v, dict):
                    p = get_first_pos(v, keys)
                    if p is not None:
                        return p
                elif isinstance(v, (list, tuple)):
                    p = scan_for_pos(v)
                    if p is not None:
                        return p
        return None

    def scan_for_pos(v):
        if isinstance(v, (list, tuple)):
            p = as_pos(v)
            if p is not None:
                return p
            for item in v:
                p = scan_for_pos(item)
                if p is not None:
                    return p
        return None

    def gather_positions(v, out):
        if isinstance(v, dict):
            for item in v.values():
                gather_positions(item, out)
        elif isinstance(v, (list, tuple)):
            p = as_pos(v)
            if p is not None:
                out.append(p)
            else:
                for item in v:
                    gather_positions(item, out)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(n):
        if n < -1:
            return -1
        if n > 1:
            return 1
        return n

    def sign(n):
        if n > 0:
            return 1
        if n < 0:
            return -1
        return 0

    def grid_dims(grid):
        if isinstance(grid, (list, tuple)) and grid:
            h = len(grid)
            w = len(grid[0]) if isinstance(grid[0], (list, tuple)) else 0
            return w, h
        return None, None

    def cell_at(grid, x, y):
        if isinstance(grid, (list, tuple)) and 0 <= y < len(grid):
            row = grid[y]
            if isinstance(row, (list, tuple)) and 0 <= x < len(row):
                return row[x]
        return None

    def blocked(cell):
        if cell is None:
            return True
        if cell is False:
            return False
        if cell in (-1, 1, "#", "X", "W", "wall", "obstacle", "blocked", "b"):
            return True
        return False

    obs = observation if isinstance(observation, dict) else {}
    grid = obs.get("grid")
    if grid is None:
        grid = obs.get("board")
    if grid is None:
        grid = obs.get("map")

    me = get_first_pos(obs, ["agent_pos", "position", "pos", "self_pos", "me", "agent"])
    if me is None and grid is not None:
        me = get_first_pos(obs, ["spawn", "start"])
    if me is None:
