    gather_positions(obs.get("opponents"), enemies)
    gather_positions(obs.get("enemy"), enemies)
    gather_positions(obs.get("enemy_positions"), enemies)
    gather_positions(obs.get("threats"), enemies)

    territory = []
    gather_positions(obs.get("territory"), territory)
    gather_positions(obs.get("frontier"), territory)
    gather_positions(obs.get("unclaimed"), territory)

    # If explicit lists are empty, scan grid for heuristic markers.
    if grid is not None and not resources and not enemies and not territory:
